parameters.functionScript:
// Hands the Global Store its starting shape. Runs once on load, because the
// Run signal is not connected.
//
// Note for anyone copying this: Initial State is an object-typed port, and
// object ports have no editor in the property panel -- they can only be wired.
// A Function node is the shortest way to supply one.
Outputs.State = {
  messages: [],
  answer: '',
  title: 'Untitled conversation'
};

// Turns the prompt into the request the endpoint expects, then asks the stream
// node to connect. Go() is a signal output; a value output is queued onto the
// connected input before the signal that follows it, so Body and Headers have
// already landed on the stream node when Connect arrives.
const prompt = (Inputs.Prompt || '').trim();
if (!prompt) return;

Outputs.Headers = {
  'Content-Type': 'application/json',
  Authorization: 'Bearer demo-key-not-a-secret'
};
Outputs.Body = JSON.stringify({ prompt: prompt });
Outputs.Go();

// Appends your turn to the conversation held in the global store.
// The store keeps a plain array on purpose: a plain array is deep-copied into a
// snapshot, which is what lets undo restore it completely. A Noodl Array
// (Collection) would be kept by reference and only partly restorable.
const body = (Inputs.Text || '').trim();
if (!body) return;

const list = Array.isArray(Inputs.Messages) ? Inputs.Messages.slice() : [];
list.push({ id: 'you-' + Date.now() + '-' + list.length, role: 'You', text: body });

Outputs.Messages = list;
Outputs.Done();

// Appends the finished answer when the stream closes.
// The accumulated text has already landed on this node's input by the time Run
// arrives, for the same value-before-signal reason as the request builder.
const body = (Inputs.Answer || '').trim();
if (!body) return;

const list = Array.isArray(Inputs.Messages) ? Inputs.Messages.slice() : [];
list.push({ id: 'agent-' + Date.now() + '-' + list.length, role: 'Agent', text: body });

Outputs.Messages = list;
Outputs.Done();
